# Self-contained handoff bootstrap for [Yousuf's Gemini]
$ErrorActionPreference = 'Stop'
$repoRoot = (git rev-parse --show-toplevel 2>$null)
if (-not $repoRoot) {
  throw 'Run this inside your cloned hackathon-test repository.'
}
Set-Location $repoRoot

$files = @{
  '.board/gemini/board' = ''
  '.board/gemini/gemini-loop' = ''
  '.agents/hooks.json' = ''
  '.agents/hooks/session-start.ps1' = ''
  '.agents/hooks/pre-invocation.ps1' = ''
  '.agents/hooks/stop.ps1' = ''
  '.agents/rules/gemini-board.md' = ''
}

foreach ($kv in $files.GetEnumerator()) {
  $target = Join-Path $repoRoot $kv.Key
  $dir = Split-Path -Parent $target
  if (-not (Test-Path $dir)) {
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
  }
  [System.IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($kv.Value))
}

# Remove disable-autowait if present on target PC
Remove-Item -Path (Join-Path $repoRoot '.board/gemini/disable-autowait') -Force -ErrorAction SilentlyContinue

# Ensure .git/info/exclude ignores .board/gemini/ and .agents/
$excludeFile = Join-Path $repoRoot '.git/info/exclude'
$excludeText = if (Test-Path $excludeFile) { Get-Content $excludeFile -Raw } else { '' }
foreach ($pat in @('.board/gemini/', '.agents/')) {
  if ($excludeText -notmatch [regex]::Escape($pat)) {
    Add-Content -Path $excludeFile -Value "
$pat"
  }
}

# Create ../hoc-gemini worktree if not already present
$worktreePath = Join-Path (Split-Path -Parent $repoRoot) 'hoc-gemini'
if (-not (Test-Path $worktreePath)) {
  git fetch origin
  git worktree add $worktreePath origin/main
}

Write-Host '=== [Yousuf''s Gemini] handoff complete! ===' -ForegroundColor Green
Write-Host '1. .agents/ rules & hooks installed'
Write-Host '2. .board/gemini/ board tool & cursor restored (LF line endings preserved)'
Write-Host "3. Worktree ready at: $worktreePath"